//! Internal facade consumed by the code generated by `ice-rpc-macros`.
//!
//! Groups the runtime internals the `#[service]` macro depends on, so the
//! stable public API of `ice-rpc` stays small. `#[doc(hidden)]`, and **not**
//! part of the public API: its symbols are semver-exempt for the consumers of
//! `ice-rpc`, but **not** for `ice-rpc-macros`.

// ── Shutdown ────────────────────────────────────────────────────────
pub use crate::shutdown::{clear_ipc_cleanup, register_ipc_cleanup};

// ── Rx vocabulary, wire header and name limits ──────────────────────
pub use crate::types::{
    CORRELATION_ID_LEN, CallContext, EventKind, NodeId, PROTOCOL_VERSION, RpcError, RpcHeader,
    SERVICE_NAME_LEN, Sender, ServiceRef, WireEvent, call_scoped, channel, fmt_correlation_id,
    local_call_scoped, method_id_of, next_correlation_id, now_ns, parse_correlation_id,
    raw_pid_to_u32, service_id_of, unbounded_channel,
};

// The hashers the transport uses, so benchmarks price the shipped implementation.
pub use crate::hash::{FxHasher, IdentityHasher};

// Canonical terminals behind the inherent `Observable` methods.
pub use crate::types::{collect_values, first_event};

// ── Service traits implemented by the generated code ────────────────
// `ServiceInit` stays public: it is the only one a developer implements.
pub use crate::service_traits::{ServiceConsumer, ServiceLifecycle, ServiceNamed};

// ── The JSON contract, both sides ────────────────────────────────────
// One view per service: the macro implements the caller side and calls the host
// side, registered once with `set_json_dispatcher`. Gated by `json`.
#[cfg(feature = "json")]
pub use crate::json::{
    JSON_CALL_TIMEOUT, JsonCallError, JsonCallEvent, JsonCallStream, JsonDispatcher, JsonInvoker,
    JsonOutcome, JsonResult, ReadMode, dispatch_json, json_dispatcher, read_json,
    set_json_dispatcher,
};
// Host answer to wire sample: the whole envelope dispatch, one line per method.
#[cfg(feature = "json")]
pub use crate::json::event_from_json;
// Caller-side argument decoding: one line per parameter.
#[cfg(feature = "json")]
pub use crate::json::{arg_from_base64, arg_from_json, take_field};

// ── Diagnostics ─────────────────────────────────────────────────────
// The gateway's `version()` reports this instead of a hand-written literal.
pub use crate::VERSION;

// ── Lifecycle ───────────────────────────────────────────────────────
// Escape hatch for contexts the macros cannot cover (N-API gateway, tests).
pub use crate::{
    ShutdownGuard, global_cancel_token, init, init_without_ctrl_c, shutdown_and_release,
    wait_for_shutdown,
};

// ── Plumbing invoked by the generated entry points ──────────────────
pub use crate::{_ProviderService, registry_cancel_token, run_provider_inner};

#[cfg(any(
    feature = "http-threads",
    feature = "http-smol",
    feature = "http-tokio"
))]
pub use crate::start_http_server;

// ── Publish/subscribe transport ─────────────────────────────────────
// Entry points used by the generated client/server.
pub use crate::transport::PAYLOAD_ALIGNMENT;
pub use crate::transport::{
    BoxResponseFuture, CollectEmitter, DEFAULT_MAX_SLICE_LEN, DecodeFailure, OwnedEmitter,
    ResponseEmitter, ServiceDispatcher, declare_channel_max_slice_len, decode_aligned,
    emit_rpc_error, is_provider_connected, native_call, observable_to_responses,
    register_native_service, reject_undecodable, reject_undecodable_oneway, serialize_and_call,
    serialize_and_send_one_way, spawn_native_service, start_registered_channels,
    sweep_orphan_shm_markers,
};
// The JSON host helpers: the rejection paths and the shared handler body of a
// `ProviderJson` handler. Gated with the rest of the JSON host surface.
#[cfg(feature = "json")]
pub use crate::transport::{
    RequestToValue, ValueToResponse, json_host_handler, json_host_oneway_handler,
};
#[cfg(feature = "json")]
pub use crate::transport::{reject_json_dispatch, reject_json_request, reject_json_response};

// ── Dependency re-exports used by the generated code ────────────────
// No `futures`: the oneshot channel lives in `ice-rpc-rx::rt::oneshot`.
pub use async_channel;
pub use async_lock;
// Lets generated `impl` blocks name `ice_rpc::codegen::async_trait::async_trait`
// without an `async-trait` dependency in the service crate.
pub use async_trait;
// Only the JSON converters name `base64`, in both directions.
#[cfg(feature = "json")]
pub use base64;
pub use futures_lite;
// Named by the `Serialize` / `Deserialize` derives `#[payload]` adds under `json`.
#[cfg(feature = "json")]
pub use serde;
// The link-time registration surface: the expansion names `linkme` itself, so the
// whole crate is re-exported.
pub use iceoryx2;
#[cfg(feature = "monitoring")]
pub use linkme;
pub use log;
pub use rkyv;
pub use serde_json;
